<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from "vue";
import { withBase } from "vitepress";
// A real, reproducible capture of the reporter's output — regenerated by
// `npm run docs:hero` and guarded by tests/hero-asset-reproducibility.spec.ts,
// so it can never drift from what the tool actually prints. Parsed out by
// site/scripts/gen-report.mjs. The gauge and the hero card read from here —
// this page states no number it did not get from a real scan (plan §1; D1
// was this file claiming 70 beside an asset that said 75).
import scan from "./generated/report.json";
import rulesData from "../../rules/rules.data.json";

/* ----- static, SSR-stable data ----------------------------------------- */

const ruleCount = rulesData.length;
const measuredCount = rulesData.filter((r) => r.measured).length;

const evidence = [
  {
    level: "E2",
    name: "Deterministic defect",
    body: "Structurally provable from the AST — a committed .only, an unawaited assertion. Full deduction.",
  },
  {
    level: "E1",
    name: "Heuristic pattern",
    body: "A strong, correctly-positioned signal — a regex-matched hard sleep. Half deduction, never claimed as proof.",
  },
  {
    level: "E0",
    name: "Observation",
    body: "Reported for context. Never gates CI, never moves the score.",
  },
];

const features = [
  {
    r: "ᛏ",
    title: "Worthiness Score",
    body: "One number, a transparent deduction table, no black box. Gate a pull request on it.",
    to: "/guide/scoring",
  },
  {
    r: "ᛗ",
    title: "Selector Health",
    body: "Grades your Playwright locators for resilience — not just whether the run went green.",
    to: "/guide/forensics#selector-health-score",
  },
  {
    r: "ᚦ",
    title: "Runtime Forensics",
    body: "Reads real Playwright & JUnit run data to catch TRUE-FLAKE, not a static guess.",
    to: "/guide/forensics",
  },
  {
    r: "ᚨ",
    title: "CI-Integrity Rules",
    body: "Catches continue-on-error, “|| true”, and every other trick that turns red pipelines green.",
    to: "/guide/ci",
  },
  {
    r: "ᛟ",
    title: "Four Languages, One Pass",
    body: "TypeScript, Python, Java and C#/.NET — plus pytest, JUnit / TestNG and CI workflows.",
    to: "/rules/",
  },
  {
    r: "ᛉ",
    title: "Local-First",
    body: "Zero network calls while scanning. Zero telemetry. The whole audit runs in seconds.",
    to: "/reference/exit-codes#trust-model",
  },
];

/**
 * MJÖLNIR in Elder Futhark: ᛗ(mannaz) ᛃ(jera) ᛟ(othala) ᛚ(laguz)
 * ᚾ(naudiz) ᛁ(isaz) ᚱ(raidho). Left-to-right in reading order, at
 * varied size and opacity so it reads as depth rather than a banner —
 * the word is there for anyone who looks, and never claimed for anyone
 * who doesn't. Positions are fixed, not random: the hero must render
 * identically on the server and the client.
 */
const runes = [
  { g: "ᛗ", x: 7, y: 22, s: 3.6, o: 0.15, d: 0 },
  { g: "ᛃ", x: 20, y: 68, s: 2.4, o: 0.1, d: 90 },
  { g: "ᛟ", x: 33, y: 14, s: 2.8, o: 0.12, d: 180 },
  { g: "ᛚ", x: 48, y: 78, s: 2.1, o: 0.09, d: 270 },
  { g: "ᚾ", x: 63, y: 30, s: 3.1, o: 0.13, d: 360 },
  { g: "ᛁ", x: 78, y: 72, s: 2.2, o: 0.1, d: 450 },
  { g: "ᚱ", x: 90, y: 20, s: 3.4, o: 0.14, d: 540 },
];

/* ----- animation (client only) --------------------------------------- */

const RING = 339.292; // 2πr, r = 54 — full offset = empty ring
/** Ring offset for a score: 0 = full ring, RING = empty. */
const offsetFor = (n: number) => RING * (1 - n / 100);

// Rendered (and served) at the real value, so the gauge is correct with
// no JS at all — an empty ring reading 0/100 would be exactly the kind of
// unearned number the site law forbids. The count-up resets it to zero in
// onMounted, only when there is actually a client to animate it.
const score = ref(scan.score);
const dash = ref(offsetFor(scan.score));
let io: IntersectionObserver | undefined;
let raf = 0;
let revealTimer = 0;

function settleGauge() {
  score.value = scan.score;
  dash.value = offsetFor(scan.score);
}

function runGauge() {
  const target = scan.score;
  const dur = 1500;
  const start = performance.now();
  const tick = (now: number) => {
    const p = Math.min(1, (now - start) / dur);
    const e = 1 - Math.pow(1 - p, 3);
    score.value = Math.round(e * target);
    dash.value = offsetFor(e * target);
    if (p < 1) raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);
}

const copied = ref(false);
async function copyCmd() {
  try {
    await navigator.clipboard.writeText("npx mjolnir-qa@latest");
    copied.value = true;
    setTimeout(() => (copied.value = false), 1600);
  } catch {
    /* clipboard blocked — no-op */
  }
}

function revealAll() {
  document
    .querySelectorAll("[data-reveal]")
    .forEach((el) => el.classList.add("is-in"));
  settleGauge();
}

onMounted(() => {
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // No IntersectionObserver (or reduced motion): just show everything.
  if (!("IntersectionObserver" in window)) {
    revealAll();
    return;
  }

  // There is a client and it will animate, so wind the gauge back to zero
  // for the count-up. The gauge sits ~900px down, well below the fold, so
  // this never reads as a flicker.
  if (!reduce) {
    score.value = 0;
    dash.value = RING;
  }

  io = new IntersectionObserver(
    (entries) => {
      for (const en of entries) {
        if (!en.isIntersecting) continue;
        en.target.classList.add("is-in");
        if (en.target.hasAttribute("data-gauge") && !reduce) runGauge();
        else if (en.target.hasAttribute("data-gauge")) settleGauge();
        io?.unobserve(en.target);
      }
    },
    { threshold: 0.3 },
  );

  document.querySelectorAll("[data-reveal]").forEach((el) => io?.observe(el));

  // Safety net: never leave content stuck invisible.
  revealTimer = window.setTimeout(revealAll, 4000);
});

onBeforeUnmount(() => {
  io?.disconnect();
  cancelAnimationFrame(raf);
  clearTimeout(revealTimer);
});
</script>

<template>
  <main class="mj">
    <!-- ===================== HERO ===================== -->
    <section class="hero">
