  max-width: 1080px;
  margin: 0 auto;
  padding: 1rem var(--edge) 2rem;
}
.show-grid {
  display: grid;
  grid-template-columns: 1.3fr 0.7fr;
  gap: clamp(1.5rem, 5vw, 3.5rem);
  align-items: center;
}
.show-copy h2 {
  font-size: clamp(1.6rem, 4vw, 2.3rem);
  margin: 0 0 0.9rem;
}
.show-copy p {
  color: var(--vp-c-text-2);
  line-height: 1.7;
}
.show-copy .fine {
  font-size: 0.9rem;
  color: var(--vp-c-text-3);
}
.mini-cmd,
.mini-cmd code {
  font-family: var(--vp-font-family-mono);
}
.mini-cmd {
  display: inline-flex;
  gap: 0.55rem;
  margin: 1rem 0;
  padding: 0.6rem 0.9rem;
  border-radius: 8px;
  background: var(--vp-c-bg-alt);
  border: 1px solid var(--vp-c-border);
  font-size: 0.86rem;
}
.mini-cmd .prompt {
  color: var(--vp-c-brand-1);
}

.vcard {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.1rem 1.4rem;
  margin: 1.6rem auto 0;
  padding: 0.9rem 1.2rem;
  max-width: 620px;
  text-align: left;
  border: 1px solid var(--mj-hero-line);
  border-radius: 12px;
  background: rgba(8, 11, 18, 0.55);
  backdrop-filter: blur(6px);
}
.vc-ring {
  position: relative;
  width: 74px;
  aspect-ratio: 1;
  flex: none;
}
.vc-score {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--mj-display);
  font-size: 1.5rem;
  line-height: 1;
  color: var(--mj-hero-text);
  font-variant-numeric: tabular-nums;
}
.vc-main {
  min-width: 0;
}
.vc-verdict {
  font-family: var(--mj-display);
  font-size: 1.05rem;
  letter-spacing: 0.06em;
  margin: 0;
  color: var(--mj-needswork);
}
.vc-meta {
  margin: 0.15rem 0 0;
  font-size: 0.82rem;
  color: var(--mj-hero-muted);
}
.vc-ded {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.15rem;
  font-family: var(--vp-font-family-mono);
  font-size: 0.74rem;
  color: var(--mj-hero-muted);
}
.vc-ded li {
  display: grid;
  grid-template-columns: 2.4rem 4.6rem 2.4rem;
  gap: 0.35rem;
}
.vc-ded b {
  font-weight: 500;
  color: var(--mj-hero-text);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.vc-ded em {
  font-style: normal;
  text-align: right;
  color: var(--mj-needswork);
  font-variant-numeric: tabular-nums;
}
.gauge {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.gauge .track {
  fill: none;
  stroke: rgba(198, 204, 214, 0.16);
  stroke-width: 9;
}
.gauge .fill {
  fill: none;
  stroke-width: 9;
  stroke-linecap: round;
  stroke: var(--mj-needswork);
  filter: drop-shadow(0 0 8px rgba(224, 180, 67, 0.45));
  transition: stroke-dashoffset 0.1s linear;
}

/* ---------------- SCAN CAPTURE ---------------- */

/* ---------------- EVIDENCE ---------------- */
.evidence {
  max-width: 1000px;
  margin: 0 auto;
  padding: 1rem var(--edge) 2rem;
}
.ev-head {
  text-align: center;
  max-width: 62ch;
  margin: 0 auto 2.4rem;
}
.ev-head h2 {
  font-size: clamp(1.5rem, 4vw, 2.2rem);
  margin: 0 0 0.8rem;
}
.ev-head p {
