}
.ev {
  padding: 1.5rem 1.4rem;
  border-radius: 14px;
  background: var(--vp-c-bg-alt);
  border: 1px solid var(--vp-c-border);
}
.ev h3 {
  margin: 0.7rem 0 0.4rem;
