/* ---------------- FEATURES ---------------- */
.features {
  max-width: 1120px;
  margin: 0 auto;
  padding: 1rem var(--edge) 2rem;
}
.sect-title {
  text-align: center;
  font-size: clamp(1.7rem, 4.5vw, 2.6rem);
  margin: 0 0 2.6rem;
}
.feat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.1rem;
}
.feat {
  position: relative;
  display: block;
  padding: 1.6rem 1.5rem 2.4rem;
  border-radius: 14px;
  background: var(--vp-c-bg-alt);
  border: 1px solid var(--vp-c-border);
  overflow: hidden;
  color: inherit;
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}
.feat-go {
  position: absolute;
  right: 1.5rem;
  bottom: 1.2rem;
  color: var(--vp-c-brand-1);
  opacity: 0;
  transform: translateX(-6px);
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}
.feat:hover .feat-go,
.feat:focus-visible .feat-go {
  opacity: 1;
  transform: none;
}
.feat:focus-visible {
  outline: 2px solid var(--mj-ember-bright);
  outline-offset: 2px;
}
.feat::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    240px circle at var(--mx, 50%) var(--my, 0%),
    rgba(224, 180, 67, 0.14),
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.25s ease;
}
.feat:hover {
  transform: translateY(-4px);
  border-color: rgba(224, 180, 67, 0.4);
  box-shadow: 0 24px 50px -28px rgba(224, 180, 67, 0.4);
}
.feat:hover::before {
  opacity: 1;
}
.feat-rune {
  font-family: var(--mj-display);
  font-size: 1.7rem;
  color: var(--vp-c-brand-1);
  text-shadow: 0 0 20px rgba(224, 180, 67, 0.35);
}
.feat h3 {
  margin: 0.7rem 0 0.4rem;
  font-size: 1.12rem;
  font-family: var(--mj-display);
  font-weight: 600;
}
.feat p {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.65;
  color: var(--vp-c-text-2);
}

/* ---------------- COMPARE ---------------- */
.compare {
  max-width: 1000px;
  margin: 0 auto;
  padding: 1rem var(--edge) 2rem;
}
.cmp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.2rem;
  align-items: start;
}
.cmp {
  padding: 1.7rem 1.6rem;
  border-radius: 14px;
  border: 1px solid var(--vp-c-border);
}
.cmp h3 {
  margin: 0 0 0.2rem;
  font-family: var(--mj-display);
  font-size: 1.1rem;
  font-weight: 600;
}
.cmp > p {
  margin: 0 0 1rem;
  color: var(--vp-c-text-2);
  font-size: 0.92rem;
}
.cmp ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.cmp li {
  position: relative;
  padding: 0.4rem 0 0.4rem 1.4rem;
  font-size: 0.9rem;
  color: var(--vp-c-text-2);
  border-top: 1px solid var(--vp-c-gutter);
}
.cmp li::before {
  position: absolute;
  left: 0;
  top: 0.4rem;
}
.cmp-them {
  background: var(--vp-c-bg-alt);
}
.cmp-them li::before {
  content: "✕";
  color: var(--vp-c-text-3);
}
.cmp-us {
  position: relative;
  background: linear-gradient(
    180deg,
    rgba(224, 180, 67, 0.08),
    transparent 70%
  );
  border-color: rgba(224, 180, 67, 0.35);
}
.cmp-us li::before {
  content: "ᛏ";
  font-family: var(--mj-display);
  color: var(--vp-c-brand-1);
}
.cmp-mark {
  position: absolute;
  top: 1rem;
  right: 1.2rem;
  font-family: var(--mj-display);
  font-size: 1.6rem;
  color: rgba(224, 180, 67, 0.5);
}

/* ---------------- FINAL ---------------- */
.final {
  text-align: center;
  padding: 4rem var(--edge) 6rem;
  max-width: 780px;
  margin: 0 auto;
}
.final h2 {
  font-size: clamp(1.7rem, 5vw, 2.8rem);
  margin: 0 0 2rem;
}
.cmd.big {
  font-size: 1rem;
  padding: 0.85rem 0.85rem 0.85rem 1.2rem;
  background: var(--mj-forge-950);
}
.built {
  margin-top: 1.6rem;
  font-size: 0.85rem;
  color: var(--vp-c-text-2);
}
.built a {
  color: var(--vp-c-brand-1);
  font-weight: 600;
}

/* reveal */
/* Reveal-on-scroll is progressive enhancement, never a prerequisite for
   reading the page. The starting (hidden) state is gated on `.mj-anim`,
   which an inline head script in .vitepress/config.mts sets before the
   body paints. No script, no class, no hidden content — previously every
   section below the hero was `opacity: 0` with only JS to undo it, so a
   reader without JS got a hero and nothing else (plan §2, D4). */
.mj-anim [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition:
    opacity 0.7s ease,
    transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.mj-anim [data-reveal].is-in {
  opacity: 1;
  transform: none;
}
.mj-anim .feat[data-reveal] {
  transition-delay: calc(var(--i) * 80ms);
}

/* ---------------- keyframes ---------------- */
/* ---------------- runefield ---------------- */
/* The old rune field drifted forever (`floaty`, one more infinite
   animation on top of four). These settle once and then hold: the motion
   budget Check 5 enforces is unchanged at 4, and a reader who arrives
   mid-scroll sees the same still field as everyone else. */
.runefield {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.rune {
  position: absolute;
  font-family: var(--mj-display);
  line-height: 1;
  color: var(--mj-steel);
  text-shadow: 0 0 26px rgba(69, 193, 212, 0.28);
  user-select: none;
  animation: rune-settle 1.1s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes rune-settle {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.94);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes breathe {
  0%,
  100% {
    opacity: 0.75;
    transform: translateX(-50%) scale(1);
  }
  50% {
    opacity: 1;
    transform: translateX(-50%) scale(1.06);
  }
}
@keyframes flicker {
  0%,
  100% {
    opacity: 0.15;
  }
  4%,
  8% {
    opacity: 0.7;
  }
  6% {
    opacity: 0.25;
  }
  50% {
    opacity: 0.12;
  }
  52%,
  56% {
    opacity: 0.55;
  }
}
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
}
@keyframes sweep {
  to {
    background-position: -300% 0;
  }
}

/* On a phone the hero is taller than the screen, so the order decides
   what a reader sees first. Proof goes above the explanation: lockup,
   claim, verdict card, actions — and the descriptive paragraph after
   them (plan §4, Phase 3 exit gate at 390x844). */
@media (max-width: 640px) {
  .hero {
    padding: 3.6rem var(--edge) 2.4rem;
  }
  .hero-inner {
    display: flex;
    flex-direction: column;
  }
  .hero-logo {
    order: 1;
  }
  .lede {
    order: 2;
  }
  .vcard {
    order: 3;
    margin-top: 1.3rem;
  }
  .cta-row {
    order: 4;
    margin-top: 1.3rem;
  }
  .cmd {
    order: 5;
    align-self: center;
  }
  .sub {
    order: 6;
    margin-top: 1.5rem;
  }
}

/* The three-column card folds to two, with the deduction table on its
   own full-width row rather than squeezed into a third column. */
@media (max-width: 560px) {
  .vcard {
    grid-template-columns: auto 1fr;
    gap: 0.7rem 1rem;
    padding: 0.85rem 1rem;
  }
  .vc-ded {
    grid-column: 1 / -1;
    border-top: 1px solid var(--mj-hero-line);
    padding-top: 0.6rem;
  }
  .vc-ded li {
    grid-template-columns: 2.2rem 1fr 2.4rem;
  }
}

@media (max-width: 820px) {
  .show-grid,
  .cmp-grid {
    grid-template-columns: 1fr;
  }
}
@media (prefers-reduced-motion: reduce) {
  .aurora,
  .forge-glow,
  .bolt,
  .shimmer,
  .rune {
    animation: none !important;
  }
  .mj-anim [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
